import {enabledQuestions,personalCards,allPersonalCards,validateDecks} from './packs.js';
import {readAnki,makeCards} from './anki.js';
import {domains,questions,sources,tasks,verifiedDate,bankOrigins} from './content.js';
import {DAY,defaults,dayKey,schedule,sameSet,shuffle,mockSelection,streak,dueCards,validateBackup} from './core.js';
const KEY='ccar-study-studio-v1';let state=defaults(),storageFailed=false;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);state=validateBackup(parsed,questions);if(parsed.activeQuiz&&validSession(parsed.activeQuiz))state.activeQuiz=parsed.activeQuiz;}}catch{storageFailed=true;}
let view='dashboard',session=state.activeQuiz,flash=null,result=null,domainFilter=0,libraryFilter='all',search='',quizFilter='all',quizCount=10,bankFilter='all',libraryPageNumber=1;
let pendingDeck=null,importBusy=false,cardScope='all';
const app=document.querySelector('#app');
const activeQuestions=()=>enabledQuestions(questions,state);
const activeCards=()=>[...activeQuestions(),...personalCards(state)];
const studyCards=()=>{if(!['all','exam'].includes(cardScope)&&!state.personalDecks.some(d=>d.id===cardScope&&d.enabled))cardScope='all';return activeCards().filter(q=>cardScope==='all'||cardScope==='exam'&&!q.personal||q.deckId===cardScope);};
function validSession(s){return s&&['practice','mock'].includes(s.mode)&&Array.isArray(s.items)&&s.items.length>0&&s.items.length<=questions.length&&new Set(s.items.map(i=>i.id)).size===s.items.length&&s.items.every(i=>questions.some(q=>q.id===i.id)&&Array.isArray(i.order)&&i.order.length===4&&new Set(i.order).size===4&&i.order.every(x=>Number.isInteger(x)&&x>=0&&x<4))&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.items.length&&s.answers&&typeof s.answers==='object'&&Object.entries(s.answers).every(([id,a])=>s.items.some(i=>i.id===id)&&Array.isArray(a)&&new Set(a).size===a.length&&a.every(x=>Number.isInteger(x)&&x>=0&&x<4))&&Array.isArray(s.flags)&&s.flags.every(id=>s.items.some(i=>i.id===id))&&Array.isArray(s.recorded)&&s.recorded.every(id=>s.items.some(i=>i.id===id))&&typeof s.started==='number'&&Number.isFinite(s.started)&&typeof s.deadline==='number'&&Number.isFinite(s.deadline);}
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>{const p={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',cards:'<rect x="6" y="6" width="15" height="15" rx="2"/><path d="M17 3H5a2 2 0 0 0-2 2v12"/>',quiz:'<path d="M9 3h6v4H9zM9 5H5v16h14V5h-4M8 12h8M8 16h5"/>',network:'<circle cx="12" cy="5" r="3"/><circle cx="5" cy="19" r="3"/><circle cx="19" cy="19" r="3"/><path d="m10 8-4 8m8-8 4 8M8 19h8"/>',tool:'<path d="m14 6 4 4 3-3a7 7 0 0 1-9 9l-7 6-3-3 7-7a7 7 0 0 1 9-9z"/>',code:'<path d="m8 5-6 7 6 7m8-14 6 7-6 7m-3-17-2 20"/>',prompt:'<path d="M4 4h16v13H8l-4 4zM8 8h8M8 12h5"/>',layers:'<path d="m12 3 10 5-10 5L2 8zm-10 10 10 5 10-5M2 18l10 5 10-5"/>',progress:'<path d="M4 20V10m8 10V4m8 16v-7M2 22h20"/>',library:'<path d="M3 3h7v18H3zm11 0h7v18h-7zM6 7h1m10 0h1"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',book:'<path d="M12 5C9 2 4 3 2 4v16c3-2 7-2 10 0 3-2 7-2 10 0V4c-2-1-7-2-10 1zm0 0v15"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.book}</svg>`;};
function save(){state.activeQuiz=session;try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;}catch{storageFailed=true;toast('Progress could not be saved. Export a backup before leaving.');}}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4000);}
function activity(kind,isNew=false){const key=dayKey();state.activity[key]??={total:0,newCards:0,cardReviews:0};state.activity[key].total++;if(kind==='card'){if(isNew)state.activity[key].newCards++;else state.activity[key].cardReviews++;}}
function getQuestion(id){return questions.find(q=>q.id===id)||allPersonalCards(state).find(q=>q.id===id);}
function mastery(d=0){const qs=activeQuestions().filter(q=>!d||q.domain===d);return Math.round(qs.filter(q=>state.cards[q.id]?.interval>=21).length/qs.length*100);}
function accuracy(d=0){const qs=activeQuestions().filter(q=>!d||q.domain===d);let total=0,correct=0;qs.forEach(q=>{total+=state.quiz[q.id]?.attempts||0;correct+=state.quiz[q.id]?.correct||0;});return total?Math.round(correct/total*100):null;}
function originText(q){const o=bankOrigins[q.origin];return o?`${o.title} · ${o.license}`:'Study Studio original';}
function sourceLink(q){if(q.personal)return `<p class="source">Personal deck: ${esc(q.deckName)} · Imported locally; not reviewed against Anthropic documentation.</p>`;const ref=sources[q.source],o=bankOrigins[q.origin];return `<div class="source-refs"><a class="source" href="${esc(ref.url)}" target="_blank" rel="noopener noreferrer">${esc(ref.title)} ↗</a>${q.guideReference?`<span> · </span><a class="source" href="${esc(sources.guide.url)}" target="_blank" rel="noopener noreferrer">Exam guide ↗</a>`:''}${o?`<div class="attribution">Adapted from <a href="${esc(o.url)}" target="_blank" rel="noopener noreferrer">${esc(o.title)}</a> by ${esc(o.author)} · <a href="${esc(o.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(o.license)}</a>${q.reviewNotes?`<br>${esc(q.reviewNotes)}`:''}</div>`:''}</div>`;}
function bankOptions(){if(bankFilter!=='all'&&bankFilter!=='original'&&!state.enabledPacks.includes(bankFilter))bankFilter='all';return `<option value="all" ${bankFilter==='all'?'selected':''}>All enabled banks</option><option value="original" ${bankFilter==='original'?'selected':''}>Study Studio originals (79)</option>${Object.entries(bankOrigins).filter(([key])=>state.enabledPacks.includes(key)).map(([key,o])=>`<option value="${key}" ${bankFilter===key?'selected':''}>${esc(o.title)} (${questions.filter(q=>q.origin===key).length})</option>`).join('')}`;}
function matchesBank(q){return bankFilter==='all'||bankFilter==='original'&&!q.origin||q.origin===bankFilter;}
function optionReasoning(q,order=[0,1,2,3]){return q.optionExplanations?`<details class="option-reasoning"><summary>Why each option fits or fails</summary>${order.map((index,position)=>`<p><strong>${String.fromCharCode(65+position)} · ${esc(q.options[index])}</strong><br>${esc(q.optionExplanations[index])}</p>`).join('')}</details>`:'';}

function heading(title,subtitle,extra=''){return `<div class="heading"><div><div class="caption">Your study workspace</div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`;}
function domainOptions(){return `<option value="0">All exam domains</option>${domains.map(d=>`<option value="${d.id}" ${Number(domainFilter)===d.id?'selected':''}>${d.id}. ${d.short}</option>`).join('')}`;}
function stat(label,value,note){return `<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><small>${note}</small></div>`;}
function render(){const due=activeCards().filter(q=>state.cards[q.id]?.due<=Date.now()).length;app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">⌘</div><div>Study Studio<div class="caption" style="font-size:10px;margin-top:4px">CCAR-F Foundations</div></div></div><div class="caption">Workspace</div><nav>${[['dashboard','Overview','dashboard'],['cards','Flashcards','cards'],['quiz','Practice quiz','quiz'],['library','Question library','library'],['progress','Your progress','progress'],['resources','Study sources','book'],['packs','Community packs','layers'],['settings','Settings','settings']].map(([id,label,ic])=>`<button class="nav ${view===id?'active':''}" data-action="view" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='cards'&&due?`<span class="count">${due}</span>`:''}</button>`).join('')}</nav><div class="exam-note"><strong>Your next chapter.</strong>Build understanding.<br>Make it stick.<small>5 domains · 30 objectives<br>Official references, independent practice.</small></div></aside><section class="workspace"><header class="topbar"><span>Certification / <b>Architect · Foundations</b></span><div class="top-actions"><span class="date">${new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</span><span class="avatar" aria-label="Personal workspace">S</span></div></header><main>${storageFailed?'<div class="storage-warning" role="alert">Browser storage is unavailable or saved data could not be loaded. Keep a progress backup.</div>':''}${({dashboard:dashboard,cards:cardsPage,quiz:quizPage,library:libraryPage,progress:progressPage,resources:resourcesPage,settings:settingsPage,packs:packsPage}[view])()}<footer class="bottom-note">Independent study companion · Independent practice, not official exam items · Built-in questions grounded in Anthropic documentation and the exam guide. Personal decks are user-provided.<br>Progress stays in this browser. Use Settings to back it up. Documentation checked ${verifiedDate}.</footer></main></section></div>`;}
function dashboard(){const due=dueCards(activeCards(),state),today=state.activity[dayKey()]?.total||0,goal=state.settings.goal,pct=Math.min(100,Math.round(today/goal*100));return heading('A little practice. Lasting knowledge.','Pick up where you left off, one concept at a time.','<span class="pill">CCAR-F · 5 domains</span>')+`<div class="grid stats">${stat('Ready to review',due.length,'Due cards + today’s new cards')}${stat('Quiz accuracy',accuracy()===null?'—':accuracy()+'%','Across all submitted answers')}${stat('Study streak',streak(state.activity)+' <span style="font-size:16px">days</span>','A little consistency goes a long way')}${stat('Learning library',activeQuestions().length,activeCards().length+' active flashcards')}</div><div class="grid study-grid"><section class="feature"><div><div class="caption">Today’s study session</div><h2>Keep your knowledge fresh.</h2><p>${due.length?`${due.length} cards are ready. Recall the answer, then rate how well you remembered it.`:'You’re caught up with your review queue. Try a quiz or browse a new concept.'}</p><button class="btn lime" data-action="start-cards">${due.length?'Start reviewing':'View flashcards'}</button></div><div class="ring" style="--p:${pct}%"><div class="ring-inner">${today}<small>of ${goal} today</small></div></div></section><section class="panel"><h2>Put your understanding to work</h2><p>Practice decisions you’ll make as an architect.</p><div class="practice-choices"><button class="choice-row" data-action="quick"><div><strong>Quick practice</strong><span>10 questions · explanations as you go</span></div>${icon('quiz')}</button><button class="choice-row" data-action="mock"><div><strong>Timed mock exam</strong><span>60 questions · 120 minutes · weighted domains</span></div>${icon('progress')}</button></div></section></div><div class="section-title"><h2>Your exam domains</h2><span>Coverage across all 30 objectives</span></div><div class="grid domains">${domains.map(d=>`<article class="domain-card"><div class="card-top"><div class="domain-icon">${icon(d.icon)}</div><span class="weight">${d.weight}% of exam</span></div><h3>${d.name}</h3><p>${d.description}</p><div class="bar"><div style="width:${mastery(d.id)}%"></div></div><div class="domain-footer"><span>${mastery(d.id)}% retained · ${activeQuestions().filter(q=>q.domain===d.id).length} items</span><button class="text-btn" data-action="domain-quiz" data-domain="${d.id}">Practice</button></div></article>`).join('')}<article class="domain-card" style="background:#edf2e8"><div class="card-top"><div class="domain-icon">${icon('book')}</div><span class="weight">Official references</span></div><h3>Go deeper, directly<br>to the source.</h3><p>Read the exam guide and explore the documentation behind each answer.</p><div class="domain-footer" style="margin-top:auto"><span>Docs · guide · cookbook</span><button class="text-btn" data-action="view" data-view="resources">Explore sources</button></div></article></div>`;}
function cardsPage(){if(!flash)return heading('Flashcards','Practice recall before revealing the answer.')+`<section class="panel"><div class="filters"><label class="sr-only" for="card-domain">Domain</label><select id="card-domain" data-change="domain">${domainOptions()}</select><select aria-label="Flashcard deck" data-change="card-scope"><option value="all" ${cardScope==='all'?'selected':''}>All enabled flashcards</option><option value="exam" ${cardScope==='exam'?'selected':''}>CCAR-F question banks</option>${state.personalDecks.filter(d=>d.enabled).map(d=>`<option value="${d.id}" ${cardScope===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></div><h2>${dueCards(studyCards(),state,domainFilter).length} cards ready to study</h2><p>Due reviews come first, followed by up to ${state.settings.newLimit} new cards per day. Again returns in 1 minute; Hard returns in 10 minutes for a new card. Good and Easy build longer intervals.</p><div class="row"><button class="btn primary" data-action="start-cards">Start scheduled review</button><button class="btn" data-action="browse-cards">Browse all cards</button></div><p>Browsing lets you inspect cards without changing their schedule. The scheduler is a simple SM-2-inspired system, not Anki’s FSRS implementation.</p></section>`;
const q=getQuestion(flash.ids[flash.index]);if(!q)return `<section class="panel empty"><div class="caption">Session complete</div><h2>That’s a good place to pause.</h2><p>You reviewed ${flash.reviewed} cards. ${activeCards().filter(q=>state.cards[q.id]?.due>Date.now()).length} cards are scheduled for later.</p><button class="btn primary" data-action="end-cards">Back to flashcards</button><button class="btn" data-action="quick">Try a quiz</button></section>`;
return `<div class="session-meta"><span class="caption">${flash.browse?'Browse':'Scheduled review'} · ${flash.index+1} of ${flash.ids.length}</span><button class="text-btn" data-action="end-cards">End session</button></div><section class="panel study-card"><div class="row"><span class="pill">${q.personal?esc(q.deckName):'D'+q.domain+' · '+tasks[q.task]}</span><button class="text-btn" data-action="bookmark" data-id="${q.id}">${state.bookmarks.includes(q.id)?'★ Saved':'☆ Save'}</button></div><div class="flash-face"><div class="caption">${flash.revealed?'Answer':'Recall first'}</div><h2>${esc(q.front)}</h2>${flash.revealed?`<p>${esc(q.answer)}</p>${sourceLink(q)}`:'<p style="font-size:14px;color:var(--muted)">Say the answer in your own words.</p>'}</div>${!flash.revealed?'<button class="btn primary" style="width:100%" data-action="reveal">Reveal answer <small>Space</small></button>':flash.browse?'<button class="btn primary" data-action="next-card">Next card</button>':`<div class="rating-grid">${['again','hard','good','easy'].map((r,i)=>`<button class="btn ${r==='good'?'primary':''}" data-action="rate" data-rating="${r}">${i+1} · ${r[0].toUpperCase()+r.slice(1)}<small>${intervalText(schedule(state.cards[q.id],r).due-Date.now())}</small></button>`).join('')}</div>`}</section>`;}
function intervalText(ms){return ms<3600000?Math.max(1,Math.round(ms/60000))+' min':ms<DAY?Math.round(ms/3600000)+' hr':Math.round(ms/DAY*10)/10+' days';}
function startCards(browse=false){const ids=(browse?studyCards().filter(q=>!domainFilter||q.domain===Number(domainFilter)):dueCards(studyCards(),state,domainFilter)).map(q=>q.id);view='cards';if(!ids.length){flash=null;toast('No cards due within today’s limits. Browse the library or return later.');}else flash={ids,index:0,revealed:false,browse,reviewed:0};render();}
function rateCard(rating){const q=getQuestion(flash.ids[flash.index]);if(!q||!flash.revealed||flash.browse)return;const isNew=!state.cards[q.id];state.cards[q.id]=schedule(state.cards[q.id],rating);activity('card',isNew);flash.reviewed++;flash.index++;flash.revealed=false;save();render();}
function quizPage(){if(result)return resultsPage();if(session)return sessionPage();const filtered=quizPool();return heading('Practice quiz','Build understanding with feedback, or rehearse under time pressure.')+`<div class="grid study-grid"><section class="panel"><h2>Make this session yours</h2><p>Choose a domain and focus. Questions and answer order are shuffled each session.</p><div class="setting"><label for="quiz-domain">Exam domain</label><select id="quiz-domain" data-change="domain">${domainOptions()}</select></div><div class="setting"><label for="quiz-bank">Question bank</label><select id="quiz-bank" data-change="bank-filter">${bankOptions()}</select></div><div class="setting"><label for="quiz-focus">Focus</label><select id="quiz-focus" data-change="quiz-filter">${[['all','All questions'],['mistakes','Last answered incorrectly'],['unseen','Not attempted yet'],['saved','Saved questions']].map(([id,label])=>`<option value="${id}" ${id===quizFilter?'selected':''}>${label}</option>`).join('')}</select></div><div class="setting"><label for="quiz-count">Session length</label><select id="quiz-count" data-change="quiz-count">${[5,10,20,questions.length].map(n=>`<option value="${n}" ${n===quizCount?'selected':''}>${n===questions.length?'All available':n+' questions'}</option>`).join('')}</select></div><p>${filtered.length} questions match your selection.</p><button class="btn primary" data-action="start-quiz" ${!filtered.length?'disabled':''}>Start practice</button></section><section class="panel"><div class="caption">Exam rehearsal</div><h2 style="margin-top:12px">Timed mock exam</h2><p>60 questions in 120 minutes, sampled by the official domain weights. Includes single and multiple-response items; multiple-response scoring requires every correct selection.</p><div class="row" style="margin:24px 0"><span class="pill">60 items</span><span class="pill">120 minutes</span></div><p>Feedback appears after submission. Mark questions for review and move between items. Your active session is saved, and the timer continues if you close the browser.</p><button class="btn primary" data-action="mock">Start mock exam</button><p>Practice percentages are not Anthropic’s scaled exam scores or a prediction of passing.</p></section></div>`;}
function quizPool(){return activeQuestions().filter(q=>matchesBank(q)&&(!domainFilter||q.domain===Number(domainFilter))&&(quizFilter==='all'||quizFilter==='mistakes'&&state.quiz[q.id]?.lastCorrect===false||quizFilter==='unseen'&&!state.quiz[q.id]||quizFilter==='saved'&&state.bookmarks.includes(q.id)));}
function startQuiz(mode='practice',quick=false){if(session){view='quiz';result=null;render();toast('Your unfinished session has been resumed.');return;}const qs=mode==='mock'?mockSelection(activeQuestions()):shuffle(quick?activeQuestions():quizPool()).slice(0,quick?10:quizCount);if(!qs.length){toast('No questions match these filters.');return;}session={mode,items:qs.map(q=>({id:q.id,order:shuffle([0,1,2,3])})),index:0,answers:{},flags:[],recorded:[],started:Date.now(),deadline:mode==='mock'?Date.now()+120*60000:0};result=null;view='quiz';save();render();}
function recordQuestion(id){if(session.recorded.includes(id))return;const q=getQuestion(id),ok=sameSet(session.answers[id]||[],q.correct);const p=state.quiz[id]||{attempts:0,correct:0};state.quiz[id]={attempts:p.attempts+1,correct:p.correct+(ok?1:0),lastCorrect:ok};session.recorded.push(id);activity('quiz');}
function sessionPage(){const item=session.items[session.index],q=getQuestion(item.id),selected=session.answers[q.id]||[],checked=session.mode==='practice'&&session.recorded.includes(q.id),ok=sameSet(selected,q.correct);return `<div class="session-meta"><span class="caption">${session.mode==='mock'?'Timed mock':'Practice'} · ${session.index+1} / ${session.items.length}</span><div class="row">${session.mode==='mock'?'<span class="timer" id="timer"></span>':''}<button class="text-btn" data-action="quit-quiz">Save & leave</button></div></div><section class="panel study-card"><div class="row"><span class="pill">D${q.domain} · Objective ${q.task}</span><span class="pill">${q.correct.length>1?'Select '+q.correct.length:'Choose one'}</span><button class="text-btn" data-action="flag">${session.flags.includes(q.id)?'⚑ Marked':'⚐ Mark for review'}</button></div><h2>${esc(q.question)}</h2><div class="options">${item.order.map((index,position)=>`<button class="option ${selected.includes(index)?'selected':''} ${checked&&q.correct.includes(index)?'correct':''} ${checked&&selected.includes(index)&&!q.correct.includes(index)?'wrong':''}" data-action="answer" data-index="${index}" aria-pressed="${selected.includes(index)}" ${checked?'disabled':''}><span class="letter">${String.fromCharCode(65+position)}</span><span>${esc(q.options[index])}</span></button>`).join('')}</div>${checked?`<div class="feedback ${ok?'':'wrong'}"><h3>${ok?'Correct — well reasoned.':'A concept to revisit.'}</h3><p><strong>Answer:</strong> ${q.correct.map(i=>esc(q.options[i])).join('; ')}</p><p>${esc(q.explanation)}</p>${optionReasoning(q,item.order)}${sourceLink(q)}</div>`:''}<div class="card-actions"><button class="btn" data-action="prev-question" ${session.index===0?'disabled':''}>Previous</button><button class="text-btn" data-action="bookmark" data-id="${q.id}">${state.bookmarks.includes(q.id)?'★ Saved':'☆ Save'}</button>${session.mode==='practice'&&!checked?`<button class="btn primary" data-action="check" ${selected.length!==q.correct.length?'disabled':''}>Check answer</button>`:`<button class="btn primary" data-action="next-question">${session.index===session.items.length-1?'Finish session':'Next question'}</button>`}</div>${session.mode==='mock'?`<div class="card-actions"><span style="font-size:13px;color:var(--muted)">${Object.values(session.answers).filter(a=>a.length).length} answered · ${session.flags.length} marked</span><button class="btn" data-action="submit-mock">Submit mock exam</button></div>`:''}</section><div class="qnav" aria-label="Question navigation">${session.items.map((it,i)=>`<button class="${session.answers[it.id]?.length?'done':''} ${i===session.index?'current':''} ${session.flags.includes(it.id)?'flagged':''}" data-action="jump" data-index="${i}" aria-label="Question ${i+1}${session.flags.includes(it.id)?', marked for review':''}">${i+1}</button>`).join('')}</div>`;}
function finishQuiz(force=false){if(!session)return;const missing=session.items.filter(i=>!session.answers[i.id]?.length).length;if(!force&&missing&&!confirm(`${missing} unanswered questions will count as incorrect. Submit this session?`))return;session.items.forEach(it=>recordQuestion(it.id));const correct=session.items.filter(it=>sameSet(session.answers[it.id]||[],getQuestion(it.id).correct)).length;result={...session,correct,total:session.items.length};state.sessions.push({date:Date.now(),mode:session.mode,correct,total:session.items.length});state.sessions=state.sessions.slice(-100);session=null;save();render();window.scrollTo(0,0);}
function resultsPage(){const pct=Math.round(result.correct/result.total*100);return heading('Session complete','Use the explanations to turn mistakes into understanding.')+`<div class="grid stats">${stat('Practice score',pct+'%',result.correct+' correct out of '+result.total)}${stat('To revisit',result.total-result.correct,'Unanswered items count as incorrect')}${stat('Time spent',Math.round((Date.now()-result.started)/60000)+' min',result.mode==='mock'?'Timed mock exam':'Practice session')}${stat('Next step','Recall','Review related flashcards')}</div><section class="panel"><div class="row"><button class="btn primary" data-action="new-quiz">New practice session</button><button class="btn" data-action="result-mistakes">Practice mistakes</button><button class="btn" data-action="start-cards">Review flashcards</button></div><p>This is an unscaled practice percentage. It does not convert to the official exam score.</p></section><div class="results-review">${result.items.map((it,i)=>{const q=getQuestion(it.id),a=result.answers[q.id]||[],ok=sameSet(a,q.correct);return `<article class="panel result-question"><span class="caption">${i+1} · D${q.domain} · ${ok?'Correct':'Revisit'}</span><h3>${esc(q.question)}</h3><p>Your answer: ${a.length?a.map(j=>esc(q.options[j])).join('; '):'Unanswered'}<br><strong>Correct: ${q.correct.map(j=>esc(q.options[j])).join('; ')}</strong></p><p>${esc(q.explanation)}</p>${optionReasoning(q,it.order)}${sourceLink(q)}</article>`;}).join('')}</div>`;}
function libraryPage(){const filtered=activeQuestions().filter(q=>matchesBank(q)&&(!domainFilter||q.domain===Number(domainFilter))&&(libraryFilter==='all'||libraryFilter==='saved'&&state.bookmarks.includes(q.id)||libraryFilter==='mistakes'&&state.quiz[q.id]?.lastCorrect===false)&&[q.question,q.front,tasks[q.task],q.task,originText(q)].join(' ').toLowerCase().includes(search.toLowerCase()));const pages=Math.max(1,Math.ceil(filtered.length/30));libraryPageNumber=Math.min(libraryPageNumber,pages);const visible=filtered.slice((libraryPageNumber-1)*30,libraryPageNumber*30);return heading('Question library','Explore the bank, inspect answers, and save concepts to revisit.')+`<div class="filters"><input type="search" id="library-search" aria-label="Search questions" placeholder="Search a concept, question, or objective…" value="${esc(search)}" data-input="search"><select aria-label="Filter by domain" data-change="domain">${domainOptions()}</select><select aria-label="Question bank" data-change="bank-filter">${bankOptions()}</select><select aria-label="Filter questions" data-change="library-filter">${[['all','All items'],['saved','Saved'],['mistakes','Mistakes']].map(([k,l])=>`<option value="${k}" ${libraryFilter===k?'selected':''}>${l}</option>`).join('')}</select></div><div class="section-title"><h2>${filtered.length} learning items</h2><button class="text-btn" data-action="export-anki">Export Anki TSV</button></div><div class="library">${visible.length?visible.map(q=>`<details class="panel library-item"><summary><small>D${q.domain} · Objective ${q.task} · ${esc(tasks[q.task])}<br>${esc(originText(q))}</small>${esc(q.question)}</summary><p><strong>${q.correct.map(i=>esc(q.options[i])).join('; ')}</strong></p><p>${esc(q.explanation)}</p>${optionReasoning(q)}<div class="row">${sourceLink(q)}<button class="text-btn" data-action="bookmark" data-id="${q.id}">${state.bookmarks.includes(q.id)?'★ Saved':'☆ Save'}</button></div></details>`).join(''):'<section class="panel empty"><h2>No matching items</h2><p>Try another filter or search term.</p></section>'}</div>${filtered.length?`<div class="card-actions"><button class="btn" data-action="library-prev" ${libraryPageNumber===1?'disabled':''}>Previous page</button><span class="source">Page ${libraryPageNumber} of ${pages} · ${visible.length} shown</span><button class="btn" data-action="library-next" ${libraryPageNumber===pages?'disabled':''}>Next page</button></div>`:''}`;}

function progressPage(){const total=Object.values(state.activity).reduce((n,a)=>n+a.total,0),attempted=activeQuestions().filter(q=>state.quiz[q.id]).length;const dates=Array.from({length:28},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(27-i));return dayKey(d.getTime());});return heading('Your progress','A clear view of what you’ve practiced and what needs attention.')+`<div class="grid stats">${stat('Study actions',total,'Quiz answers + rated flashcards')}${stat('Bank coverage',Math.round(attempted/activeQuestions().length*100)+'%',attempted+' of '+activeQuestions().length+' questions attempted')}${stat('Cards retained',mastery()+'%','Cards with intervals of at least 21 days')}${stat('Study streak',streak(state.activity)+' days','Consecutive days with study activity')}</div><section class="panel" style="margin-bottom:22px"><h2>Last 28 days</h2><div class="heatmap" aria-label="Daily study activity">${dates.map(d=>`<span class="${state.activity[d]?.total?'studied':''}" title="${d}: ${state.activity[d]?.total||0} study actions"></span>`).join('')}</div><p>Each green square is a day you studied. Retained means a scheduled interval of at least 21 days; it is a learning indicator, not a passing prediction.</p></section><section class="panel"><h2>Domain coverage</h2><table class="table"><thead><tr><th>Domain</th><th>Attempted</th><th>Accuracy</th><th>Retained</th></tr></thead><tbody>${domains.map(d=>{const qs=activeQuestions().filter(q=>q.domain===d.id);return `<tr><td>${d.id}. ${d.short}</td><td>${qs.filter(q=>state.quiz[q.id]).length}/${qs.length}</td><td>${accuracy(d.id)===null?'—':accuracy(d.id)+'%'}</td><td>${mastery(d.id)}%</td></tr>`;}).join('')}</tbody></table></section><section class="panel" style="margin-top:22px"><h2>Session history</h2>${state.sessions.length?`<table class="table"><thead><tr><th>Date</th><th>Session</th><th>Correct</th><th>Score</th></tr></thead><tbody>${state.sessions.slice(-10).reverse().map(s=>`<tr><td>${new Date(s.date).toLocaleDateString()}</td><td>${s.mode==='mock'?'Timed mock':'Practice'}</td><td>${s.correct}/${s.total}</td><td>${Math.round(s.correct/s.total*100)}%</td></tr>`).join('')}</tbody></table>`:'<p>Your completed quiz sessions will appear here.</p>'}</section>`;}
function resourcesPage(){const resources=[['Exam scope','Anthropic Academy · Architect Foundations','Official certification overview and entry point for the latest exam guide.','https://anthropic-partners.skilljar.com/claude-certified-architect-foundations-certification'],['Exam guide','Anthropic exam guide · PDF mirror','An Anthropic-authored guide hosted on a third-party site; used to map the five domains and 30 objectives. Obtain the latest edition through Academy.','https://nehasharma.dev/images/content/claude-exam-guide.pdf'],['Hands-on practice','Official Claude Cookbooks','Anthropic’s examples for agents, tools, retrieval, and evaluations. Optional labs reinforce the documentation behind the questions.','https://github.com/anthropics/claude-cookbooks'],['Anki companion','Open-source architect study deck','Community-maintained APKG decks. Linked for supplementary use; its question text has not been imported into this app.','https://github.com/paullarionov/claude-certified-architect/tree/main/anki']];return heading('Study sources','Read the official references behind your practice.')+`<section class="panel"><h2>A source you can check for every answer</h2><p>The bank combines 79 Study Studio originals with 255 adapted questions from three licensed, independent practice banks. Included decisions are mapped to Anthropic documentation and the Anthropic-authored exam guide. Ambiguous or unsupported candidates were excluded; several questions were corrected for current terminology. Community Anki decks remain supplementary resources. The cookbook is a hands-on companion; no API key is needed for this study app.</p><p>The guide’s task numbering anchors coverage. Current product documentation takes precedence for changing API and Claude Code behavior. No live or recalled exam questions are included.</p>${resources.map(([tag,title,desc,url])=>`<article class="resource"><div class="domain-icon">${icon('book')}</div><div><span class="caption">${tag}</span><h3 style="margin-top:6px">${title}</h3><p>${desc}</p><a class="source" target="_blank" rel="noopener noreferrer" href="${url}">Open resource ↗</a></div></article>`).join('')}</section><section class="panel" style="margin-top:22px"><h2>Question bank credits</h2>${Object.entries(bankOrigins).map(([key,o])=>`<article class="resource"><div><h3>${esc(o.title)} · ${questions.filter(q=>q.origin===key).length} questions</h3><p>By ${esc(o.author)} · ${esc(o.license)}<br>${esc(o.changes)}</p><div class="row"><a class="source" href="${esc(o.url)}" target="_blank" rel="noopener noreferrer">Original project ↗</a><a class="source" href="${esc(o.licenseUrl)}" target="_blank" rel="noopener noreferrer">License ↗</a><a class="source" href="licenses/${key}.txt" target="_blank" rel="noopener noreferrer">Included license notice</a></div></div></article>`).join('')}<p>Adapted CC BY-SA questions retain CC BY-SA 4.0; other portions retain their stated licenses. Attribution also travels with Anki exports. Imported questions have stable IDs, so bank updates preserve study progress.</p></section><section class="panel" style="margin-top:22px"><h2>Documentation used by the question bank</h2>${Object.entries(sources).filter(([key])=>questions.some(q=>q.source===key)).map(([key,s])=>`<div class="resource"><div><h3>${esc(s.title)}</h3><a class="source" href="${s.url}" target="_blank" rel="noopener noreferrer">Read documentation ↗</a></div></div>`).join('')}</section>`;}
function packsPage(){const fields=pendingDeck?Math.max(...pendingDeck.notes.map(n=>n.fields.length)):0;const options=selected=>Array.from({length:fields},(_,i)=>`<option value="${i}" ${i===selected?'selected':''}>Field ${i+1}</option>`).join('');return heading('Community packs','Choose your study material. Your progress stays on this device.')+`<section class="panel"><h2>Your question banks</h2><p>The 79 original questions are always included. Optional community packs add reviewed quiz questions and flashcards. Unchecking a pack pauses its reviews and hides its questions; its history is kept. An unfinished quiz can still be completed.</p><div class="pack-row"><strong>Study Studio originals</strong><span class="pill">79 · Always included</span></div>${Object.entries(bankOrigins).map(([key,o])=>`<label class="pack-row"><input type="checkbox" data-pack="${key}" ${state.enabledPacks.includes(key)?'checked':''}><span><strong>${esc(o.title)}</strong><small>${questions.filter(q=>q.origin===key).length} questions · ${esc(o.author)} · ${esc(o.license)}</small></span></label>`).join('')}<button class="text-btn" data-action="view" data-view="resources">View sources and license notices →</button></section><section class="panel" style="margin-top:22px"><h2>Your own Anki decks</h2><p>Import .apkg or Anki “Notes in Plain Text” (.txt / .tsv). Files are read on your device and never uploaded. Personal decks join flashcard reviews, not the CCAR-F quiz bank. They are not checked against Anthropic documentation.</p><p>This imports text and cloze cards. Choose the front/back fields below. Anki templates, reversed-card generation, images, audio, and Anki scheduling are not carried over; cards start with this app’s scheduler. Limits: 25 MB per file, 10,000 personal cards total.</p><input type="file" id="deck-file" accept=".apkg,.txt,.tsv" class="sr-only"><button class="btn primary" data-action="import-deck" ${importBusy?'disabled':''}>${importBusy?'Reading deck…':'Import Anki deck'}</button>${pendingDeck?`<div class="import-preview"><h3>Preview before adding</h3><div class="setting"><label for="deck-name">Deck name</label><input id="deck-name" maxlength="200" value="${esc(pendingDeck.name)}"></div><div class="setting"><label for="front-field">Front / cloze field</label><select id="front-field">${options(0)}</select></div><div class="setting"><label for="back-field">Back / extra field</label><select id="back-field"><option value="-1" ${fields===1?'selected':''}>None (cloze only)</option>${options(fields>1?1:-1)}</select></div><p>${pendingDeck.notes.length} notes. Preview of the first note’s fields:</p>${pendingDeck.notes[0].fields.map((f,i)=>`<p class="field-preview"><strong>Field ${i+1}</strong><br>${esc(f.slice(0,600))}</p>`).join('')}<p>Reimporting the same file updates its local deck and keeps matching card history.</p><div class="row"><button class="btn primary" data-action="confirm-deck">Add to my flashcards</button><button class="btn" data-action="cancel-deck">Cancel</button></div></div>`:''}${state.personalDecks.map(d=>`<label class="pack-row"><input type="checkbox" data-personal="${esc(d.id)}" ${d.enabled?'checked':''}><span><strong>${esc(d.name)}</strong><small>${d.cards.length} personal flashcards · Only in this browser</small></span></label>`).join('')}<p>Export a progress backup in Settings to transfer your decks, pack choices, and history. Browser data can be cleared by your browser; backups protect your daily progress.</p></section>`;}

function settingsPage(){return heading('Study settings','Set a sustainable pace and keep your progress safe.')+`<div class="grid settings-grid"><section class="panel"><h2>Your daily pace</h2><p><button class="text-btn" data-action="view" data-view="packs">Manage community packs & import Anki decks →</button></p>${[['newLimit','New flashcards per day'],['reviewLimit','Scheduled reviews per day'],['goal','Daily study-action goal']].map(([k,l])=>`<div class="setting"><label for="${k}">${l}</label><input type="number" id="${k}" data-setting="${k}" min="1" max="500" value="${state.settings[k]}"></div>`).join('')}<p>Values from 1 to 500. A quiz answer or flashcard rating counts as one study action.</p><button class="btn primary" data-action="save-settings">Save study settings</button></section><section class="panel"><h2>Progress & portability</h2><p>Your progress is stored in this browser, on this device. Export a backup before clearing browser data or moving devices.</p><div class="row"><button class="btn" data-action="export">Export progress JSON</button><button class="btn" data-action="import">Restore backup</button><input id="import-file" class="sr-only" type="file" accept="application/json,.json"></div><h3 style="margin-top:30px">Study in Anki</h3><p>Export flashcards from enabled question banks as a tab-separated text file. Import it into Anki as Front, Back, Tags, with HTML enabled. Review schedules are not transferred.</p><button class="btn" data-action="export-anki">Export Anki TSV</button><h3 style="margin-top:30px">Reset this browser</h3><p>This clears saved study progress, bookmarks, and active sessions.</p><button class="btn danger" data-action="reset">Reset progress</button></section></div>`;}
function download(name,text,type){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportAnki(){const text='#separator:Tab\n#html:true\n#columns:Front\tBack\tTags\n'+activeQuestions().map(q=>[esc(q.front),esc(q.answer)+`<br><a href="${esc(sources[q.source].url)}">${esc(sources[q.source].title)}</a>`+(q.origin?`<br>Adapted from <a href="${esc(bankOrigins[q.origin].url)}">${esc(bankOrigins[q.origin].title)}</a> by ${esc(bankOrigins[q.origin].author)} · <a href="${esc(bankOrigins[q.origin].licenseUrl)}">${esc(bankOrigins[q.origin].license)}</a>. ${esc(bankOrigins[q.origin].changes)}`:''),'CCAR-F::D'+q.domain+' objective::'+q.task+' bank::'+(q.origin||'original')].map(x=>x.replace(/\t|\n|\r/g,' ')).join('\t')).join('\n');download('ccar-f-flashcards.tsv',text,'text/tab-separated-values;charset=utf-8');toast('Anki flashcards exported.');}
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
if(action==='view'){view=b.dataset.view;render();window.scrollTo(0,0);}
else if(action==='start-cards')startCards();else if(action==='browse-cards')startCards(true);else if(action==='end-cards'){flash=null;view='cards';render();}
else if(action==='reveal'){flash.revealed=true;render();}else if(action==='rate')rateCard(b.dataset.rating);else if(action==='next-card'){flash.index++;flash.revealed=false;render();}
else if(action==='quick')startQuiz('practice',true);else if(action==='mock')startQuiz('mock');else if(action==='start-quiz')startQuiz();
else if(action==='domain-quiz'){domainFilter=Number(b.dataset.domain);quizFilter='all';quizCount=10;view='quiz';result=null;render();}
else if(action==='bookmark'){const id=b.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();b.textContent=state.bookmarks.includes(id)?'★ Saved':'☆ Save';}
else if(action==='answer'){const q=getQuestion(session.items[session.index].id),idx=Number(b.dataset.index);let a=session.answers[q.id]||[];a=q.correct.length===1?[idx]:a.includes(idx)?a.filter(i=>i!==idx):[...a,idx];session.answers[q.id]=a;save();render();}
else if(action==='check'){recordQuestion(session.items[session.index].id);save();render();}
else if(action==='next-question'){if(session.index===session.items.length-1)finishQuiz();else{session.index++;save();render();}}
else if(action==='prev-question'){session.index--;save();render();}else if(action==='jump'){session.index=Number(b.dataset.index);save();render();}
else if(action==='flag'){const id=session.items[session.index].id;session.flags=session.flags.includes(id)?session.flags.filter(x=>x!==id):[...session.flags,id];save();render();}
else if(action==='quit-quiz'){view='dashboard';save();render();toast('Session saved. Open Practice quiz to continue.');}
else if(action==='submit-mock')finishQuiz();else if(action==='library-prev'){libraryPageNumber--;render();window.scrollTo(0,0);}else if(action==='library-next'){libraryPageNumber++;render();window.scrollTo(0,0);}else if(action==='new-quiz'){result=null;render();}else if(action==='result-mistakes'){result=null;quizFilter='mistakes';domainFilter=0;bankFilter='all';startQuiz();}
else if(action==='import-deck')app.querySelector('#deck-file').click();
else if(action==='cancel-deck'){pendingDeck=null;render();}
else if(action==='confirm-deck'){try{const name=app.querySelector('#deck-name').value.trim();const {cards,skipped}=makeCards(pendingDeck,Number(app.querySelector('#front-field').value),Number(app.querySelector('#back-field').value));if(!cards.length)throw new Error('No text cards found with these fields.');const previous=state.personalDecks;const deck={id:pendingDeck.id,name,enabled:true,cards};const updated=[...previous.filter(d=>d.id!==deck.id),deck];validateDecks(updated);const serialized=JSON.stringify({...state,personalDecks:updated});if(serialized.length>3000000)throw new Error('Local storage limit reached. Import a smaller deck.');localStorage.setItem(KEY,serialized);state.personalDecks=updated;cardScope=deck.id;domainFilter=0;pendingDeck=null;save();render();toast(cards.length+' cards imported locally'+(skipped?' · '+skipped+' empty notes skipped':'')+'.');}catch(err){toast(err.message);}}
else if(action==='save-settings'){const inputs=[...app.querySelectorAll('[data-setting]')];if(inputs.some(i=>!i.checkValidity()||!Number.isInteger(Number(i.value)))){toast('Enter whole numbers between 1 and 500.');return;}inputs.forEach(i=>state.settings[i.dataset.setting]=Number(i.value));save();toast('Your study pace is saved.');}
else if(action==='export'){download('ccar-f-progress-'+dayKey()+'.json',JSON.stringify(state,null,2),'application/json');toast('Progress backup exported.');}
else if(action==='export-anki')exportAnki();else if(action==='import')app.querySelector('#import-file').click();else if(action==='reset'){if(confirm('Reset all progress in this browser? Export a backup first if you want to keep it.')){state=defaults();session=null;flash=null;result=null;cardScope='all';bankFilter='all';save();render();toast('Progress reset.');}}
});
app.addEventListener('change',async e=>{const t=e.target;if(t.dataset.change){libraryPageNumber=1;if(t.dataset.change==='card-scope'){cardScope=t.value;domainFilter=0;}if(t.dataset.change==='bank-filter')bankFilter=t.value;if(t.dataset.change==='domain')domainFilter=Number(t.value);if(t.dataset.change==='quiz-filter')quizFilter=t.value;if(t.dataset.change==='quiz-count')quizCount=Number(t.value);if(t.dataset.change==='library-filter')libraryFilter=t.value;render();}
if(t.dataset.pack){state.enabledPacks=t.checked?[...new Set([...state.enabledPacks,t.dataset.pack])]:state.enabledPacks.filter(id=>id!==t.dataset.pack);flash=null;bankFilter='all';libraryPageNumber=1;save();render();}
if(t.dataset.personal){if(!t.checked&&cardScope===t.dataset.personal)cardScope='all';const deck=state.personalDecks.find(d=>d.id===t.dataset.personal);deck.enabled=t.checked;flash=null;save();render();}
if(t.id==='deck-file'&&t.files[0]){importBusy=true;const file=t.files[0];render();try{pendingDeck=await readAnki(file);}catch(err){toast(err.message);}finally{importBusy=false;render();}}
if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>5000000)throw new Error('Backup is too large.');const next=validateBackup(JSON.parse(await t.files[0].text()),questions);if(!confirm('Replace this browser’s study progress with the backup?'))return;state=next;session=null;flash=null;result=null;cardScope='all';bankFilter='all';save();render();toast('Progress restored.');}catch(err){toast(err.message||'Unable to restore backup.');}}});
app.addEventListener('input',e=>{if(e.target.dataset.input==='search'){search=e.target.value;libraryPageNumber=1;const start=e.target.selectionStart;render();const input=app.querySelector('#library-search');input.focus();input.setSelectionRange(start,start);}});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(view==='cards'&&flash){if(e.code==='Space'&&!flash.revealed){e.preventDefault();flash.revealed=true;render();}else if(flash.revealed&&!flash.browse&&['1','2','3','4'].includes(e.key)){e.preventDefault();rateCard(['again','hard','good','easy'][Number(e.key)-1]);}}});
function tick(){if(!session||session.mode!=='mock')return;const left=session.deadline-Date.now();if(left<=0){finishQuiz(true);toast('Time is up. Your mock exam has been submitted.');return;}const el=document.querySelector('#timer');if(el){const seconds=Math.ceil(left/1000);el.textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}}
render();tick();setInterval(tick,1000);
